import fs from'node:fs';import{createServer}from'node:http';import{hash,json}from'./bounded-source-hash-20261026.mjs';import assert from'node:assert/strict';
const root='F:/VisibleMedicine/staging/20261026-plexus-ultrasound-review',packet=json(root+'/REVIEW_PACKET.json');assert.equal(hash(root+'/REVIEW_PACKET.json'),'202af80bde058415b4349d531a1a5556075e6d42bc72ee26db552f4aa18d29a2');for(const r of packet.figures)assert.equal(hash(root+'/'+r.file),r.sha256);const allowed=new Map([['/','review.html'],...packet.figures.map(r=>['/'+r.file,r.file])]);const server=createServer((req,res)=>{const file=allowed.get(new URL(req.url,'http://127.0.0.1').pathname);if(!file){res.writeHead(404);res.end();return;}res.writeHead(200,{'content-type':file.endsWith('.jpg')?'image/jpeg':'text/html; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff'});res.end(fs.readFileSync(root+'/'+file));});server.listen(0,'127.0.0.1',()=>console.log(JSON.stringify({pid:process.pid,port:server.address().port,localOnly:true})));process.stdin.setEncoding('utf8');process.stdin.on('data',t=>{if(t.trim()==='stop')server.close(()=>process.exit(0));});process.stdin.resume();
